#define AA_PASS 21
// Shared HDR surface, planar mirror views, Hi-Z SSR and environment fallback.
cbuffer Parameters : register(b0)
{
    float4 aa[16];
}
Texture2D<float4> sceneColor : register(t1);
Texture2D<float4> surface : register(t2);
Texture2D<float4> sceneDepth : register(t3);
Texture2D<float4> environmentMap : register(t4);
Texture2D<float4> hiz1 : register(t5);
Texture2D<float4> hiz2 : register(t6);
Texture2D<float4> hiz3 : register(t7);
Texture2D<float4> hiz4 : register(t8);
Texture2D<float4> hiz5 : register(t11);
Texture2D<float4> hiz6 : register(t12);
Texture2D<float4> hiz7 : register(t13);
Texture2D<float4> hiz8 : register(t14);
Texture2D<float4> hiz9 : register(t15);
Texture2D<float4> hiz10 : register(t16);
Texture2D<float4> hiz11 : register(t17);
Texture2D<float4> hiz12 : register(t18);
SamplerState      LinearSampler : register(s9);
SamplerState      PointSampler : register(s10);
#ifndef AA_PASS
#define AA_PASS 17
#endif
static const float PI = 3.141592653589793;
float3             gammaRGB(float3 c)
{
    return pow(saturate(c), 1 / 2.2);
}
float4 rgbL(float3 c)
{
    return float4(c, dot(gammaRGB(c), float3(.299, .587, .114)));
}
void basis(float yaw, float pitch, out float3 right, out float3 up, out float3 forward)
{
    float sy = sin(yaw), cy = cos(yaw), sp = sin(pitch), cp = cos(pitch);
    right   = float3(cy, 0, -sy);
    up      = float3(-sy * sp, cp, -cy * sp);
    forward = float3(sy * cp, sp, cy * cp);
}
float3 eye()
{
    float3 r, u, f;
    basis(aa[2].x, aa[4].z, r, u, f);
    return f * aa[4].x;
}
float3 viewPosition(float3 p)
{
    float3 r, u, f;
    basis(aa[2].x, aa[4].z, r, u, f);
    return float3(dot(p, r), dot(p, u), aa[4].x - dot(p, f));
}
float3 viewDirection(float3 d)
{
    float3 r, u, f;
    basis(aa[2].x, aa[4].z, r, u, f);
    return float3(dot(d, r), dot(d, u), -dot(d, f));
}
float4 projectWorld(float3 p, float yaw, float pitch, float distance)
{
    float3 r, u, f;
    basis(yaw, pitch, r, u, f);
    float3 v = float3(dot(p, r), dot(p, u), distance - dot(p, f));
    return float4(v.x * 1.85 / (aa[0].x / aa[0].y), v.y * 1.85, v.z * .99 - .1, v.z);
}
float2 projectView(float3 p)
{
    return float2(p.x * 1.85 / (aa[0].x / aa[0].y), -p.y * 1.85) / max(p.z, .00001) * .5 + .5;
}
float3 cameraRay(float2 uv)
{
    float3 r, u, f;
    basis(aa[2].x, aa[4].z, r, u, f);
    float2 n = uv * 2 - 1;
    return normalize(r * n.x * (aa[0].x / aa[0].y) / 1.85 - u * n.y / 1.85 - f);
}
float3 worldPosition(float2 uv, float z)
{
    float3 r, u, f;
    basis(aa[2].x, aa[4].z, r, u, f);
    float2 n = uv * 2 - 1;
    return eye() + r * n.x * z * (aa[0].x / aa[0].y) / 1.85 - u * n.y * z / 1.85 - f * z;
}
float3 atlasLevel(float3 direction, uint level)
{
    float2 uv = float2(atan2(direction.z, direction.x) / (2 * PI) + .5, acos(clamp(direction.y, -1, 1)) / PI);
    float  w = max(1.0, 256.0 / exp2(float(level))), h = max(1.0, 128.0 / exp2(float(level))), y = 256 - w;
    float2 p = float2(clamp(uv.x * w, .5, w - .5), y + clamp(uv.y * h, .5, h - .5));
    return environmentMap.SampleLevel(LinearSampler, p / 256, 0).rgb;
}
float3 environment(float3 direction, float roughness)
{
    float level = saturate(roughness) * 8;
    uint  low   = uint(floor(level));
    return lerp(atlasLevel(normalize(direction), low), atlasLevel(normalize(direction), min(low + 1, 8)), frac(level))
           * aa[10].w;
}
// Static procedural room shared by the visible mesh and the HDR cubemap capture.
bool probeScene()
{
    return aa[8].y < -1.5;
}
float3 probeRoomColor(float3 p, uint wall)
{
    float3 color = wall == 2 ? float3(.65, .055, .035) : wall == 3 ? float3(.035, .18, .65) : float3(.5, .52, .55);
    float2 uv    = wall == 0 || wall == 4 ? p.xz : wall == 1 ? p.xy : p.zy;
    float2 grid  = abs(frac(uv) - .5);
    if (max(grid.x, grid.y) > .475)
        color *= .3;
    if (wall == 1 && p.y > .35 && p.y < 1.65 && abs(p.x) < 2.9)
    {
        uint stripe = uint(floor(p.x + 3));
        color = stripe % 3 == 0 ? float3(.9, .55, .035) : stripe % 3 == 1 ? float3(.05, .7, .2) : float3(.65, .05, .7);
    }
    return color;
}
void probeProp(uint id, out float3 center, out float3 size, out float3 color)
{
    center = float3(-2.6 + id * 2.6, -.15 + id * .22, -2.8);
    size   = float3(.7, 1.7 + id * .44, .7);
    color  = id == 0 ? float3(.95, .25, .025) : id == 1 ? float3(.08, .7, .23) : float3(.15, .3, .9);
}
float3 probeShade(float3 p, float3 n, float3 color)
{
    if (abs(p.z + 4) < .005 && abs(p.x) < .9 && p.y > 2.1 && p.y < 2.5)
        return float3(5, 4.4, 3.5);
    return color * (.2 + 1.25 * saturate(dot(n, normalize(float3(-.5, 1.2, 1.3)))));
}
float3 probeCapture(float3 direction)
{
    float3 origin    = aa[11].xyz;
    float  nearest   = 1000;
    float3 hitNormal = 0, hitColor = 0, hitPosition = 0;
    for (uint wall = 0; wall < 5; wall++)
    {
        uint  axis  = wall == 0 || wall == 4 ? 1 : wall == 1 ? 2 : 0;
        float plane = wall == 0 ? -1 : wall == 4 ? 3 : wall == 1 || wall == 2 ? -4 : 4;
        if (abs(direction[axis]) < .00001)
            continue;
        float  t = (plane - origin[axis]) / direction[axis];
        float3 p = origin + direction * t;
        if (
          t > .001 && t < nearest && p.x >= -4.001 && p.x <= 4.001 && p.y >= -1.001 && p.y <= 3.001 && p.z >= -4.001
          && p.z <= 4.001)
        {
            nearest         = t;
            hitNormal       = 0;
            hitNormal[axis] = wall == 0 || wall == 1 || wall == 2 ? 1 : -1;
            hitPosition     = p;
            hitColor        = probeRoomColor(p, wall);
        }
    }
    float3 safe = float3(
      direction.x >= 0 ? max(direction.x, .00001) : min(direction.x, -.00001),
      direction.y >= 0 ? max(direction.y, .00001) : min(direction.y, -.00001),
      direction.z >= 0 ? max(direction.z, .00001) : min(direction.z, -.00001));
    for (uint id = 0; id < 3; id++)
    {
        float3 center, size, color;
        probeProp(id, center, size, color);
        float3 a = (center - size * .5 - origin) / safe, b = (center + size * .5 - origin) / safe;
        float3 low = min(a, b), high = max(a, b);
        float  t = max(max(low.x, low.y), low.z), farT = min(min(high.x, high.y), high.z);
        if (t > .001 && farT >= t && t < nearest)
        {
            nearest      = t;
            hitPosition  = origin + direction * t;
            hitColor     = color;
            float3 delta = (hitPosition - center) / (size * .5), ab = abs(delta);
            hitNormal = ab.x >= ab.y && ab.x >= ab.z ? float3(delta.x > 0 ? 1 : -1, 0, 0)
                        : ab.y >= ab.z               ? float3(0, delta.y > 0 ? 1 : -1, 0)
                                                     : float3(0, 0, delta.z > 0 ? 1 : -1);
        }
    }
    return nearest < 999 ? probeShade(hitPosition, hitNormal, hitColor) : environment(direction, 0);
}
float3 probeFaceDirection(uint face, float2 uv)
{
    float2 p = uv * 2 - 1;
    return normalize(
      face == 0   ? float3(1, -p.y, -p.x)
      : face == 1 ? float3(-1, -p.y, p.x)
      : face == 2 ? float3(p.x, 1, p.y)
      : face == 3 ? float3(p.x, -1, -p.y)
      : face == 4 ? float3(p.x, -p.y, 1)
                  : float3(-p.x, -p.y, -1));
}
float4 probeMeta(uint index, uint row)
{
    return hiz7.Load(int3(index * 5 + row, 0, 0));
}
float3 probeTint(uint index)
{
    return index == 0   ? float3(1, .12, .08)
           : index == 1 ? float3(.08, 1, .15)
           : index == 2 ? float3(.08, .25, 1)
                        : float3(1, .7, .04);
}
float4 probeTexture(uint index, float2 uv)
{
    return index == 0   ? hiz3.SampleLevel(LinearSampler, uv, 0)
           : index == 1 ? hiz4.SampleLevel(LinearSampler, uv, 0)
           : index == 2 ? hiz5.SampleLevel(LinearSampler, uv, 0)
                        : hiz6.SampleLevel(LinearSampler, uv, 0);
}
float3 probeSampleLevel(float3 d, uint level, uint index)
{
    float3 a = abs(d);
    uint   face;
    float2 uv;
    if (a.x >= a.y && a.x >= a.z)
    {
        face = d.x >= 0 ? 0 : 1;
        uv   = float2(d.x >= 0 ? -d.z : d.z, -d.y) / a.x;
    }
    else if (a.y >= a.z)
    {
        face = d.y >= 0 ? 2 : 3;
        uv   = float2(d.x, d.y >= 0 ? d.z : -d.z) / a.y;
    }
    else
    {
        face = d.z >= 0 ? 4 : 5;
        uv   = float2(d.z >= 0 ? d.x : -d.x, -d.y) / a.z;
    }
    float  size = float(128 >> level), offset = 512 - 4 * size;
    float2 pixel = float2((face % 3) * size, offset + (face / 3) * size) + clamp((uv * .5 + .5) * size, .5, size - .5);
    return probeTexture(index, pixel / float2(384, 512)).rgb;
}
float3 probeSample(float3 direction, float roughness, uint index)
{
    float mip = roughness * 7;
    uint  low = uint(floor(mip));
    return lerp(
      probeSampleLevel(direction, low, index), probeSampleLevel(direction, min(low + 1, 7), index), frac(mip));
}
float4 probeAtlas(float2 pixel)
{
    uint  level = 0;
    float size = 128, offset = 0;
    for (uint k = 1; k < 8; k++)
    {
        float s = float(128 >> k), o = 512 - 4 * s;
        if (pixel.y >= o)
        {
            level  = k;
            size   = s;
            offset = o;
        }
    }
    if (pixel.x >= size * 3 || pixel.y >= offset + size * 2)
        return 0;
    uint   face = uint(pixel.x / size) + uint((pixel.y - offset) / size) * 3;
    float2 uv   = frac(float2(pixel.x, pixel.y - offset) / size);
    float3 n    = probeFaceDirection(face, uv);
    if (level == 0)
        return float4(probeCapture(n), 1);
    float  rough = float(level) / 7, alpha = rough * rough;
    float3 up = abs(n.z) < .999 ? float3(0, 0, 1) : float3(1, 0, 0), t = normalize(cross(up, n)), b = cross(n, t);
    float3 sum    = 0;
    float  weight = 0;
    for (uint j = 0; j < 64; j++)
    {
        uint bits = j;
        bits      = (bits << 16) | (bits >> 16);
        bits      = ((bits & 0x55555555) << 1) | ((bits & 0xAAAAAAAA) >> 1);
        bits      = ((bits & 0x33333333) << 2) | ((bits & 0xCCCCCCCC) >> 2);
        bits      = ((bits & 0x0F0F0F0F) << 4) | ((bits & 0xF0F0F0F0) >> 4);
        bits      = ((bits & 0x00FF00FF) << 8) | ((bits & 0xFF00FF00) >> 8);
        float xi = float(bits) * 2.3283064365386963e-10, phi = 2 * PI * (float(j) + .5) / 64;
        float cosTheta = sqrt((1 - xi) / (1 + (alpha * alpha - 1) * xi)),
              sinTheta = sqrt(max(0, 1 - cosTheta * cosTheta));
        float3 h       = t * cos(phi) * sinTheta + b * sin(phi) * sinTheta + n * cosTheta;
        float3 l       = normalize(2 * dot(n, h) * h - n);
        float  w       = saturate(dot(n, l));
        if (w > 0)
        {
            sum += probeCapture(l) * w;
            weight += w;
        }
    }
    return float4(sum / max(weight, .0001), 1);
}

bool planarScene()
{
    return aa[8].y < 0 && aa[8].y > -1.5;
}
float3 mirrorPoint(float3 p, uint plane)
{
    if (plane == 1)
        p.y = -2 - p.y;
    if (plane == 2)
        p.z = -6.4 - p.z;
    return p;
}
#if AA_PASS == 17
struct Geometry
{
    float3 p;
    float3 normal;
    float3 color;
    float  roughness;
};
Geometry probeGeometry(uint id, float time)
{
    Geometry g;
    g.roughness       = 1.25;
    const uint tri[6] = {0, 1, 3, 0, 3, 2};
    if (id < 30)
    {
        uint   wall = id / 6, q = tri[id % 6];
        float2 uv = float2(q & 1, (q >> 1) & 1);
        if (wall == 0 || wall == 4)
        {
            g.p      = float3(uv.x * 8 - 4, wall == 0 ? -1 : 3, uv.y * 8 - 4);
            g.normal = float3(0, wall == 0 ? 1 : -1, 0);
        }
        else if (wall == 1)
        {
            g.p      = float3(uv.x * 8 - 4, uv.y * 4 - 1, -4);
            g.normal = float3(0, 0, 1);
        }
        else
        {
            g.p      = float3(wall == 2 ? -4 : 4, uv.y * 4 - 1, uv.x * 8 - 4);
            g.normal = float3(wall == 2 ? 1 : -1, 0, 0);
        }
        g.color = float3(float(wall), 0, 0);
        return g;
    }
    id -= 30;
    if (id < 108)
    {
        uint   object = id / 36, face = (id % 36) / 6, q = tri[id % 6], axis = face / 2;
        float  sign = (face & 1) ? 1 : -1;
        float2 uv   = float2(q & 1, (q >> 1) & 1) * 2 - 1;
        float3 center, size;
        probeProp(object, center, size, g.color);
        g.normal = axis == 0 ? float3(sign, 0, 0) : axis == 1 ? float3(0, sign, 0) : float3(0, 0, sign);
        g.p      = center
              + (axis == 0   ? float3(sign, uv)
                 : axis == 1 ? float3(uv.x, sign, uv.y)
                             : float3(uv, sign))
                  * size * .5;
        return g;
    }
    if (id >= 7020)
    {
        uint probeIndex = (id - 7020) / 108;
        uint marker = (id - 7020) % 108, axis = marker / 36, face = (marker % 36) / 6, q = tri[marker % 6],
             normalAxis = face / 2;
        float  sign     = (face & 1) ? 1 : -1;
        float2 uv       = float2(q & 1, (q >> 1) & 1) * 2 - 1;
        g.normal     = normalAxis == 0 ? float3(sign, 0, 0) : normalAxis == 1 ? float3(0, sign, 0) : float3(0, 0, sign);
        float3 size  = float3(.045, .045, .045);
        size[axis]   = .4;
        float3 local = normalAxis == 0   ? float3(sign, uv)
                       : normalAxis == 1 ? float3(uv.x, sign, uv.y)
                                         : float3(uv, sign);
        g.p          = probeMeta(probeIndex, 0).xyz + local * size * .5;
        g.color      = aa[9].w > 1.5 ? probeTint(probeIndex) : float3(1, .6, .015);
        g.roughness  = 2;
        return g;
    }
    id -= 108;
    uint  object = id / 2304, k = id % 2304, cell = k / 6, q = tri[k % 6];
    float u = (float(cell % 24) + float(q & 1)) / 24 * 2 * PI, v = (float(cell / 24) + float((q >> 1) & 1)) / 16 * PI;
    g.normal = float3(sin(v) * cos(u), cos(v), sin(v) * sin(u));
    g.p      = float3(-2.5 + object * 2.5 + sin(time) * .25, -.2, .9) + g.normal * .75;
    if (aa[9].w > 1.5)
        g.p = float3(object == 1 ? sin(time) * 3 : -2.5 + object * 2.5, -.2, object == 1 ? 1.6 : -.5) + g.normal * .75;
    g.color     = float3(.025, .028, .035);
    g.roughness = aa[8].w;
    return g;
}
Geometry geometry(uint id, float time)
{
    if (probeScene())
        return probeGeometry(id, time);
    Geometry g;
    g.roughness       = .2;
    const uint tri[6] = {0, 1, 3, 0, 3, 2};
    if (id < 6)
    {
        uint q      = tri[id];
        g.p         = float3((q & 1) ? 4 : -4, -1, (q & 2) ? 6 : -4);
        g.normal    = float3(0, 1, 0);
        g.color     = float3(.055, .065, .08);
        g.roughness = .035;
        return g;
    }
    id -= 6;
    if (id < 19 * 36)
    {
        uint   object = id / 36, face = (id % 36) / 6, q = tri[id % 6];
        float2 uv = float2(q & 1, (q >> 1) & 1) * 2 - 1;
        float3 center, size;
        if (object < 4)
        {
            center  = float3(-2.4 + object * 1.6, -.4 + object * .18, -2.2);
            size    = float3(.55, 1.2 + object * .36, .55);
            g.color = object == 0   ? float3(.85, .16, .06)
                      : object == 1 ? float3(.06, .55, .85)
                      : object == 2 ? float3(.75, .55, .08)
                                    : float3(.16, .7, .28);
        }
        else if (object < 16)
        {
            center  = float3(-3.3 + (object - 4) * .6, -.85, 2.4);
            size    = float3(.06, .3, .06);
            g.color = float3(.7, .7, .72);
            if (planarScene() && object < 8)
            {
                uint frame = object - 4;
                center     = frame < 2 ? float3(frame == 0 ? -3.86 : 3.86, 1.1, -3.16)
                                       : float3(0, frame == 2 ? -1.06 : 3.26, -3.16);
                size       = frame < 2 ? float3(.12, 4.44, .12) : float3(7.84, .12, .12);
                g.color    = float3(.12, .15, .19);
            }
        }
        else
        {
            float k     = object - 16;
            center      = float3(-2 + k * 2, -.6 + sin(time) * .12, -.15);
            size        = float3(.65, .8, .65);
            g.color     = k == 0 ? float3(.9, .28, .04) : k == 1 ? float3(.08, .7, .27) : float3(.14, .3, .9);
            g.roughness = .15 + k * .2;
            // Bright magenta witness behind the initial camera: appears in the mirror, not the primary view.
            if (planarScene() && object == 18)
            {
                center  = float3(2, .25, 9);
                size    = float3(1, 1.6, 1);
                g.color = float3(.9, .03, .55);
            }
        }
        float sign = (face & 1) ? 1 : -1;
        uint  axis = face / 2;
        g.normal   = axis == 0 ? float3(sign, 0, 0) : axis == 1 ? float3(0, sign, 0) : float3(0, 0, sign);
        float3 p   = axis == 0 ? float3(sign, uv) : axis == 1 ? float3(uv.x, sign, uv.y) : float3(uv, sign);
        g.p        = center + p * size * .5;
        return g;
    }
    id -= 19 * 36;
    if (planarScene() && id >= 6912)
    {
        uint q      = tri[id - 6912];
        g.p         = float3((q & 1) ? 3.8 : -3.8, (q & 2) ? 3.2 : -1, -3.2);
        g.normal    = float3(0, 0, 1);
        g.color     = float3(.01, .015, .02);
        g.roughness = aa[9].y;
        return g;
    }
    uint  object = id / 2304, k = id % 2304, cell = k / 6, q = tri[k % 6];
    float u = (float(cell % 24) + float(q & 1)) / 24 * 2 * PI, v = (float(cell / 24) + float((q >> 1) & 1)) / 16 * PI;
    g.normal    = float3(sin(v) * cos(u), cos(v), sin(v) * sin(u));
    g.p         = float3(-1.7 + object * 1.7, -.44, 1) + g.normal * .55;
    g.color     = object == 0 ? float3(.8, .14, .05) : object == 1 ? float3(.9, .62, .15) : float3(.08, .35, .85);
    g.roughness = .08 + object * .22;
    return g;
}
struct Varying
{
    float4               position : SV_Position;
    float3               world : TEXCOORD0;
    float3               normal : TEXCOORD1;
    float3               color : TEXCOORD2;
    float                roughness : TEXCOORD3;
    float4               current : TEXCOORD4;
    float4               previous : TEXCOORD5;
    nointerpolation uint sky : TEXCOORD6;
};
Varying VSMain(uint id : SV_VertexID)
{
    Varying o;
    uint    skyStart = probeScene() ? uint(7050 + 108 * aa[9].w) : planarScene() ? 7608 : 7602;
    o.sky            = id >= skyStart ? 1 : 0;
    if (o.sky)
    {
        float2 uv   = float2(((id - skyStart) << 1) & 2, (id - skyStart) & 2);
        o.position  = float4(uv * float2(2, -2) + float2(-1, 1), .999999, 1);
        o.world     = 0;
        o.normal    = 0;
        o.color     = 0;
        o.roughness = 1;
        o.current   = 0;
        o.previous  = 0;
        return o;
    }
    Geometry g  = geometry(id, aa[0].z);
    o.world     = g.p;
    o.normal    = g.normal;
    o.color     = g.color;
    o.roughness = g.roughness;
    o.current   = projectWorld(mirrorPoint(g.p, uint(aa[5].w)), aa[2].x, aa[4].z, aa[4].x);
    o.previous  = projectWorld(mirrorPoint(geometry(id, aa[2].w).p, uint(aa[5].w)), aa[2].y, aa[4].w, aa[4].y);
    o.position  = o.current;
    o.position.xy += aa[1].xy * 2 / aa[0].xy * float2(1, -1) * o.position.w;
    return o;
}
struct SurfaceOutput
{
    float4 color : SV_Target0;
    float4 motion : SV_Target1;
    float4 normalRoughness : SV_Target2;
    float4 depth : SV_Target3;
};
SurfaceOutput PSMain(Varying i)
{
    SurfaceOutput o;
    if (i.sky)
    {
        float2 uv = (i.position.xy / (aa[0].xy * (aa[0].w == 4 ? 2 : 1))) - aa[1].xy / aa[0].xy;
        float3 d  = cameraRay(uv), r, u, f;
        if (aa[5].w == 1)
            d.y = -d.y;
        if (aa[5].w == 2)
            d.z = -d.z;
        basis(aa[2].y, aa[4].w, r, u, f);
        float3 motionDirection = cameraRay(uv);
        float3 old             = float3(dot(motionDirection, r), dot(motionDirection, u), -dot(motionDirection, f));
        float2 prev            = projectView(old);
        o.color                = rgbL(environment(d, 0) * aa[2].z);
        o.motion               = float4(prev - uv, 1, 1);
